public class HeapTuningDemonstration {
    // VM Arguments to analyze heap layout:
    // -Xms4g -Xmx4g -XX:+UseG1GC -XX:MaxMetaspaceSize=512m -XX:+PrintGCDetails

    public static void main(String[] args) throws InterruptedException {
        long totalMemory = Runtime.getRuntime().totalMemory();
        long maxMemory = Runtime.getRuntime().maxMemory();

        System.out.println("Initial Heap (Xms): " + (totalMemory / (1024 * 1024)) + " MB");
        System.out.println("Maximum Heap (Xmx): " + (maxMemory / (1024 * 1024)) + " MB");

        // Allocating temporary objects to trigger Eden churn and minor GC
        for (int i = 0; i < 100_000; i++) {
            byte[] shortLivedAllocation = new byte[1024 * 10]; // 10 KB per iteration
            if (i % 10_000 == 0) {
                Thread.sleep(10); // Permit GC threads to catch up
            }
        }
    }
}
